#include <bits/stdc++.h>
using namespace std;const int N=48;const long long P=1e9+7;long long a[32][N][N],f[N],g[N];int id(int m,int u,int p){return(m*3+u)*4+p;}void d(int r,int m,int u,int p,int o,int c,int s){if(r==2){a[0][s][id(o,u,c)]++;return;}if(m>>r&1){d(r+1,m,u,p,o,c,s);return;}if(!r&&!(m&2))d(2,m,u,p,o,c,s);d(r+1,m,u,p,o|1<<r,c,s);if(u<2&&!c&&!(p>>r&1))d(r+1,m,u+1,p,o,c|1<<r,s);}void init(){for(int m=0;m<4;m++)for(int u=0;u<3;u++)for(int p=0;p<4;p++)d(0,m,u,p,0,0,id(m,u,p));for(int z=1;z<32;z++)for(int i=0;i<N;i++)for(int k=0;k<N;k++)if(a[z-1][i][k])for(int j=0;j<N;j++)a[z][i][j]=(a[z][i][j]+a[z-1][i][k]*a[z-1][k][j])%P;}int main(){ios::sync_with_stdio(0);cin.tie(0);init();int t;cin>>t;while(t--){int n;cin>>n;memset(f,0,sizeof f);f[id(0,0,0)]=1;for(int z=0;n;n>>=1,z++)if(n&1){memset(g,0,sizeof g);for(int i=0;i<N;i++)for(int j=0;j<N;j++)g[j]=(g[j]+f[i]*a[z][i][j])%P;memcpy(f,g,sizeof g);}long long r=0;for(int p=0;p<4;p++)r=(r+f[id(0,2,p)])%P;cout<<r<<'\n';}}
